import{_ as t,o as a,c as d,a2 as s}from"./chunks/framework.D4Tx855q.js";const m=JSON.parse('{"title":"Recipes","description":"","frontmatter":{},"headers":[],"relativePath":"recipes/index.md","filePath":"recipes/index.md","lastUpdated":1794906571000}'),r={name:"recipes/index.md"};function i(n,e,o,h,l,p){return a(),d("div",null,[...e[0]||(e[0]=[s('<h1 id="recipes" tabindex="-1">Recipes <a class="header-anchor" href="#recipes" aria-label="Permalink to &quot;Recipes&quot;">​</a></h1><p>Complete, step-by-step answers to tasks most apps need. Each recipe starts from what you want to build, shows the Kotlin and the Svelte side together, and uses only Ktor, SvelteKit and what ktor-svelte already does, so you can copy it and adapt the names.</p><h2 id="pick-a-recipe" tabindex="-1">Pick a recipe <a class="header-anchor" href="#pick-a-recipe" aria-label="Permalink to &quot;Pick a recipe&quot;">​</a></h2><table tabindex="0"><thead><tr><th>You want to...</th><th>Recipe</th><th>Level</th><th>Time</th></tr></thead><tbody><tr><td>Go from a Kotlin class to a table, a detail page and forms</td><td><a href="./crud-in-minutes">CRUD in minutes</a></td><td>Beginner</td><td>10 min</td></tr><tr><td>Let people sign in and stay signed in</td><td><a href="./sessions">Sign in with a session cookie</a></td><td>Beginner</td><td>20 min</td></tr><tr><td>Give users roles that decide what they may do</td><td><a href="./role-based-app">A role-based app</a></td><td>Intermediate</td><td>30 min</td></tr><tr><td>Add pages and routes that only admins can use</td><td><a href="./admin-area">Add an admin area</a></td><td>Intermediate</td><td>20 min</td></tr><tr><td>Accept files with progress and shared size and type rules</td><td><a href="./uploads">Upload files</a></td><td>Beginner</td><td>15 min</td></tr><tr><td>Show long lists one page at a time</td><td><a href="./pagination">Page through long lists</a></td><td>Beginner</td><td>15 min</td></tr><tr><td>Update results while someone types</td><td><a href="./search-as-you-type">Search as you type</a></td><td>Beginner</td><td>10 min</td></tr><tr><td>Push changes from the server to open pages</td><td><a href="./live-updates">Stream live updates</a></td><td>Intermediate</td><td>15 min</td></tr><tr><td>Offer the site in several languages, with local dates and prices</td><td><a href="./multilingual-site">A multilingual site</a></td><td>Intermediate</td><td>30 min</td></tr></tbody></table><h2 id="build-an-app-from-them" tabindex="-1">Build an app from them <a class="header-anchor" href="#build-an-app-from-them" aria-label="Permalink to &quot;Build an app from them&quot;">​</a></h2><p>The recipes fit together. A typical team app uses them in this order:</p><ol><li><a href="./crud-in-minutes">CRUD in minutes</a> for the first resource.</li><li><a href="./sessions">Sign in with a session cookie</a> to put it behind a login.</li><li><a href="./role-based-app">A role-based app</a> and <a href="./admin-area">Add an admin area</a> when not everyone may do everything.</li><li><a href="./pagination">Page through long lists</a> and <a href="./search-as-you-type">Search as you type</a> once the lists grow.</li><li><a href="./uploads">Upload files</a>, <a href="./live-updates">Stream live updates</a> and <a href="./multilingual-site">A multilingual site</a> as the app needs them.</li></ol><p><code>examples/showcase</code> is such an app: a team board with sign-in, roles, an admin area, uploads, paged tables and two languages. Read its source next to the recipes, or see <a href="./../examples">Examples</a>.</p><h2 id="smaller-answers" tabindex="-1">Smaller answers <a class="header-anchor" href="#smaller-answers" aria-label="Permalink to &quot;Smaller answers&quot;">​</a></h2><p>Some tasks are a few lines and live on the feature pages:</p><table tabindex="0"><thead><tr><th>You want to...</th><th>Where</th></tr></thead><tbody><tr><td>Keep a typed value in a cookie</td><td><a href="./sessions#typed-cookies">Typed cookies</a></td></tr><tr><td>Ask for consent before setting a cookie</td><td><a href="./sessions#cookie-consent">Cookie consent</a></td></tr><tr><td>Warn before a session ends</td><td><a href="./../features/auth#when-the-session-ends">When the session ends</a></td></tr><tr><td>Check one field on the server while someone types</td><td><a href="./../features/validation#checks-only-the-server-can-make">Checks only the server can make</a></td></tr><tr><td>Show a message from a route as a toast</td><td><a href="./../features/calling-the-api#toasts-from-the-server">Toasts from the server</a></td></tr><tr><td>Check health from a load balancer</td><td><a href="./../features/endpoints#health-endpoint">Health endpoint</a></td></tr></tbody></table>',11)])])}const u=t(r,[["render",i]]);export{m as __pageData,u as default};
